void MainWindow::indexLogRow(const QJsonObject &row){
 QString source=row["source"].toString(),message=row["text"].toString();qint64 bucket=qint64(row["time"].toDouble()/5.);
 QString key=WorkbenchState::logSignature(source,message)+"|"+QString::number(bucket);
 QJsonObject group=logGroups_.value(key);
 if(group.isEmpty()){group=QJsonObject{{"source",source},{"level",row["level"].toString()},{"first_time",row["time"]},{"first_text",message},{"count",0}};}
 group["last_time"]=row["time"];group["text"]=message;group["count"]=group["count"].toInt()+1;
 group["raw"]=QString::fromUtf8(QJsonDocument(row).toJson(QJsonDocument::Compact));
 logGroups_.insert(key,group);
 if(logGroups_.size()>4000){QString oldest;double stamp=1e30;for(auto it=logGroups_.begin();it!=logGroups_.end();++it){double value=it.value()["last_time"].toDouble();if(value<stamp){stamp=value;oldest=it.key();}}if(!oldest.isEmpty())logGroups_.remove(oldest);}
}
void MainWindow::rebuildLogIndex(){logGroups_.clear();for(auto value:logRows_)indexLogRow(value.toObject());}
void MainWindow::logRow(QJsonObject row){logRows_.append(row);while(logRows_.size()>10000)logRows_.removeFirst();indexLogRow(row);logsDirty_=true;}
void MainWindow::filterLogs(){
 QMap<QString,int> sources;for(auto value:logRows_)sources[value.toObject()["source"].toString()]++;
 logSources_->clear();auto *all=new QListWidgetItem("全部来源  "+QString::number(logRows_.size()),logSources_);all->setData(Qt::UserRole,"全部来源");for(auto it=sources.begin();it!=sources.end();++it){auto *item=new QListWidgetItem(it.key()+"  "+QString::number(it.value()),logSources_);item->setData(Qt::UserRole,it.key());item->setToolTip(it.key());}
 QVector<QJsonObject> rows;bool grouped=logGroup_&&logGroup_->isChecked();
 if(grouped){for(auto value:logGroups_)rows<<value;}else{for(auto value:logRows_){auto row=value.toObject();row["first_time"]=row["time"];row["first_text"]=row["text"];row["last_time"]=row["time"];row["count"]=1;row["raw"]=QString::fromUtf8(QJsonDocument(row).toJson(QJsonDocument::Compact));rows<<row;}}
 std::sort(rows.begin(),rows.end(),[](const QJsonObject &a,const QJsonObject &b){return a["last_time"].toDouble()<b["last_time"].toDouble();});
 QVector<QJsonObject> visible;for(auto row:rows){QString source=row["source"].toString(),level=row["level"].toString(),message=row["text"].toString(),first=row["first_text"].toString();if(logSource_->currentText()!="全部来源"&&!source.contains(logSource_->currentText()))continue;double stamp=row["last_time"].toDouble();if(logTime_->currentIndex()!=2&&stamp<QDateTime::currentMSecsSinceEpoch()/1000.-(logTime_->currentIndex()==0?3600.:86400.))continue;if(logLevel_->currentIndex()!=0&&level!=logLevel_->currentText())continue;QString keyword=logSearch_->text();if(!keyword.isEmpty()&&!message.contains(keyword,Qt::CaseInsensitive)&&!first.contains(keyword,Qt::CaseInsensitive))continue;visible<<row;}
 logTable_->setUpdatesEnabled(false);logTable_->setRowCount(visible.size());for(int r=0;r<visible.size();++r){auto row=visible[r];QString source=row["source"].toString(),level=row["level"].toString(),message=row["text"].toString();int count=row["count"].toInt();QString shown=message.section('\n',0,0);if(grouped&&count>1)shown+=QString("  · 5 秒内 %1 次").arg(count);QStringList cols={QDateTime::fromMSecsSinceEpoch(qint64(row["last_time"].toDouble()*1000)).toString("HH:mm:ss.zzz"),level,source,shown};for(int i=0;i<4;++i)logTable_->setItem(r,i,new QTableWidgetItem(cols[i]));QString detail=row["raw"].toString();if(grouped&&count>1)detail=QString("合并 %1 条同模板日志（完整原文已落盘）\n首次：%2\n最后：%3\n\n最后一条原文：\n%4").arg(count).arg(QDateTime::fromMSecsSinceEpoch(qint64(row["first_time"].toDouble()*1000)).toString("yyyy-MM-dd HH:mm:ss.zzz")).arg(QDateTime::fromMSecsSinceEpoch(qint64(row["last_time"].toDouble()*1000)).toString("yyyy-MM-dd HH:mm:ss.zzz")).arg(message);logTable_->item(r,3)->setData(Qt::UserRole,detail);logTable_->item(r,3)->setData(Qt::UserRole+1,QString::fromUtf8(QJsonDocument(row).toJson(QJsonDocument::Compact)));}
 logTable_->setUpdatesEnabled(true);if(logStats_)logStats_->setText(QString("显示 %1 条 · 原始 %2 条 · %3；完整原始日志保存在磁盘").arg(visible.size()).arg(logRows_.size()).arg(grouped?"高频日志合并已开启":"正在显示逐条日志"));
 if(!logPause_->isChecked())logTable_->scrollToBottom();
}
